def solve(inputs: dict) -> float:
    # Extract parameters from inputs, with fallbacks for naming
    def find(*keys):
        for k in keys:
            if k in inputs:
                return inputs[k]
        return None
    # Try common key names
    x = None
    a = None
    m = None
    steps = None
    for k, v in inputs.items():
        lk = k.lower()
        if 'start' in lk or lk in ('x', 'x0', 'seed', 'initial'):
            x = v
        elif 'add' in lk or 'const' in lk or lk in ('c', 'b'):
            a = v
        elif 'mod' in lk or lk in ('m', 'modulus', 'n'):
            m = v
        elif 'step' in lk or 'iter' in lk or lk in ('k', 't', 'n_steps'):
            steps = v
    # Fallback: use numeric values in order if not resolved
    vals = list(inputs.values())
    if x is None or a is None or m is None or steps is None:
        # attempt positional: start, add, mod, steps
        nums = [v for v in vals]
        if x is None and len(nums) > 0: x = nums[0]
        if a is None and len(nums) > 1: a = nums[1]
        if m is None and len(nums) > 2: m = nums[2]
        if steps is None and len(nums) > 3: steps = nums[3]
    x = int(x); a = int(a); m = int(m); steps = int(steps)
    for _ in range(steps):
        x = (x * x + a) % m
    return float(x)

