def solve(inputs: dict) -> float:
    terms = None
    for k, v in inputs.items():
        if isinstance(v, (list, tuple)):
            terms = v
            break
    if terms is None:
        # maybe stored differently
        for k, v in inputs.items():
            if 'term' in k.lower() or 'a' == k.lower() or 'cf' in k.lower():
                terms = v
    terms = [int(t) for t in terms]
    p_prev2 = 1        # p_{-1}
    p_prev1 = terms[0] # p_0
    if len(terms) == 1:
        return float(p_prev1)
    for i in range(1, len(terms)):
        p = terms[i] * p_prev1 + p_prev2
        p_prev2 = p_prev1
        p_prev1 = p
    return float(p_prev1)

